import {supabase} from './auth-client.mjs';
import {playerParameters,playerLink} from './player-model.mjs';
import {collectionTotals,cardsInSet,selectedAlbumSet,cardsForAlbumList} from './player-album-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./album-data/',import.meta.url),el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
let data,player,selected=0,filter='all',preview=false;const inventory=new Map();
const nameOf=set=>set.name.replace(/ Set$/,'');
function trackerLinks(){for(const id of ['open-tracker','detail-tracker']){const url=new URL('./my-album.html',import.meta.url);if(selected)url.searchParams.set('set',selected);$(id).href=url.href}}
function showSet(set){if(!Number.isInteger(set)||set<1||set>data.sets.length)return;selected=set;filter='all';render();if(!$('album-detail').open)$('album-detail').showModal();$('album-detail').querySelector('.modal-body').scrollTop=0}
function openCard(card){const q=inventory.get(card.number)||0;$('card-title').textContent='#'+card.number+' · '+card.name;$('card-detail-art').src=new URL(card.image,root);$('card-detail-art').alt=card.name;$('card-description').textContent=card.stars+' stars'+(card.gold?' · Gold card':'')+' · '+(q?'Owned: '+q:'Missing');$('card-availability').textContent=q>1?(q-1)+' extra '+(q===2?'copy':'copies')+'. Trade eligibility depends on the player’s preferences and current game rules.':q===1?'This player has one copy.':'This player has not collected this card.';$('card-dialog').showModal()}
function createCard(card){const q=inventory.get(card.number)||0,b=el('button',undefined,'public-card'+(q?'':' missing')+(card.gold?' gold':'')),image=el('img'),stars=el('img');b.type='button';b.dataset.card=card.number;b.setAttribute('aria-label','#'+card.number+' '+card.name+', '+card.stars+' stars, '+(q?'owned '+q:'missing'));image.src=new URL(card.image,root);image.alt='';image.className='card-art';image.loading='lazy';image.width=582;image.height=834;stars.src=new URL('./tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',import.meta.url);stars.alt='';stars.className='card-stars';b.append(image,stars,el('span','No. '+card.number,'card-name'),el('span',q>1?'×'+q:q?'Owned':'Missing','card-state'+(q>1?' duplicate':'')));b.onclick=()=>openCard(card);return b}
function openAlbumList(kind){
 const cards=cardsForAlbumList(data.cards,inventory,kind),titles={'lf':'LF Card','lf-gold':'LF Gold Card','ft':'FT Card'},descriptions={'lf':'Missing non-gold cards','lf-gold':'Missing gold cards','ft':'Duplicate cards'};
 $('album-list-title').textContent=titles[kind];$('album-list-description').textContent=descriptions[kind]+' · '+cards.length+' '+(cards.length===1?'card':'cards')+(kind==='ft'?' · '+collectionTotals(cards,inventory).extras+' extra copies':'');
 $('album-list-cards').replaceChildren(...cards.map(createCard));$('album-list-empty').hidden=cards.length>0;$('album-list-empty').textContent=kind==='ft'?'This player has no duplicate cards.':'This player has collected every '+(kind==='lf-gold'?'gold':'non-gold')+' card.';$('album-list-dialog').showModal();
}
function render(){const totals=collectionTotals(data.cards,inventory);$('album-progress').textContent=String(cardsForAlbumList(data.cards,inventory,'lf').length);$('gold-progress').textContent=String(cardsForAlbumList(data.cards,inventory,'lf-gold').length);$('banner-progress-label').textContent=totals.collected+' / '+data.cards.length;$('duplicate-progress').textContent=totals.extras;$('collection-progress').value=totals.collected;$('collection-progress').max=data.cards.length;$('album-overview').hidden=false;trackerLinks();
 if(!$('album-set-grid').childElementCount)$('album-set-grid').replaceChildren(...data.sets.map(set=>{const count=set.cards.filter(n=>(inventory.get(n)||0)>0).length,b=el('button',undefined,'public-set'+(count===set.cards.length?' complete':'')),art=el('img'),progress=el('progress');b.type='button';b.setAttribute('aria-label',set.name+', '+count+' of '+set.cards.length+' collected');art.src=new URL(set.image,root);art.alt='';art.loading='lazy';art.width=220;art.height=220;progress.value=count;progress.max=set.cards.length;progress.setAttribute('aria-label',set.name+' progress');const chip=el('span',undefined,'set-progress-chip');progress.setAttribute('aria-label',set.name+' progress');chip.append(progress,el('span',count+' / '+set.cards.length,'set-counter'));const meta=el('span',undefined,'set-meta');meta.append(el('strong',nameOf(set)+' Set'),chip);b.append(art,meta);b.onclick=()=>showSet(set.number,{focus:true});return b}));
 if(!selected)return;const set=data.sets.find(s=>s.number===selected),count=set.cards.filter(n=>(inventory.get(n)||0)>0).length;$('set-title').textContent=set.name;$('set-image').src=new URL(set.image,root);$('set-progress').max=set.cards.length;$('set-progress').value=count;$('set-collected').textContent=count+' / '+set.cards.length;$('set-position').textContent=selected+' / '+data.sets.length;$('previous-set').disabled=selected===1;$('next-set').disabled=selected===data.sets.length;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));
 const cards=cardsInSet(data.cards,selected,filter,inventory);$('cards-empty').hidden=!!cards.length;$('album-sets').replaceChildren(...cards.map(card=>{return createCard(card)}));
}
document.querySelectorAll('[data-album-list]').forEach(button=>button.onclick=()=>openAlbumList(button.dataset.albumList));$('close-album-list').onclick=()=>$('album-list-dialog').close();
$('copy-player-uid').onclick=async()=>{const b=$('copy-player-uid');try{await navigator.clipboard.writeText(String(player.uid));b.textContent='UID copied'}catch{b.textContent='Copy failed — try again'}};
$('close-set').onclick=()=>$('album-detail').close();$('album-detail').addEventListener('close',()=>{selected=0;filter='all';trackerLinks();const url=new URL(location.href);if(url.searchParams.has('set')){url.searchParams.delete('set');history.replaceState(null,'',url)}});$('previous-set').onclick=()=>showSet(selected-1,{focus:true});$('next-set').onclick=()=>showSet(selected+1,{focus:true});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('close-card').onclick=()=>$('card-dialog').close();
try{preview=['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&new URL(location.href).searchParams.get('preview')==='1';const params=preview?{album:4}:playerParameters(location.href,import.meta.url);if(!Number.isInteger(params.album)||params.album<1||params.album>32767)throw Error('Invalid album.');if(preview){player={name:'Sample collector',uid:'18691234',season:'autumn-tales',inventory:[1,2,3,4,5,6,7,8,9,55,56,57,59,60,61,91,92,93,95].map(n=>({card_number:n,quantity:[2,93,95].includes(n)?2:1}))}}else{const {data:result,error}=await supabase.rpc('get_player_album',{p_uid:params.uid,p_album:params.album});if(error)throw Error('Player albums are not available yet.');if(!result)throw Error('This player album is private or was not found.');player=result}if(player.season!=='autumn-tales')throw Error('This album is not supported yet.');const response=await fetch(new URL('autumn-tales.json',root));if(!response.ok)throw Error('Album data could not load.');data=await response.json();for(const item of player.inventory)inventory.set(item.card_number,item.quantity);selected=selectedAlbumSet(location.href,data.sets.length);if(!preview){const url=new URL(playerLink(player.uid,params.album,import.meta.url));if(selected)url.searchParams.set('set',selected);history.replaceState(null,'',url)}$('copy-player-uid').disabled=!player.uid;$('copy-player-uid').title=player.uid?'Copy UID '+player.uid:'Player UID is unavailable';$('player-uid').textContent=player.uid?'UID '+player.uid:'';$('album-status').textContent='';$('public-content').hidden=false;render();if(selected)$('album-detail').showModal()}catch(error){$('album-status').textContent=error.message;$('album-status').className='panel album-error'}
